import os

# --- Other likely mount points (tolerant) ---
print("=== Mount / upload locations ===")
for cand in ["/mnt", "/data", "/workspace", "/home", "/home/agent", "/root", "/var/data", "/srv", "/media", "/uploads", "/opt"]:
    try:
        if os.path.isdir(cand):
            print(f"  {cand}: exists -> {sorted(os.listdir(cand))[:25]}")
        else:
            print(f"  {cand}: MISSING")
    except PermissionError:
        print(f"  {cand}: (permission denied)")
    except Exception as e:
        print(f"  {cand}: (err: {e})")

# --- Filesystem-wide bounded search for spreadsheets ---
print("\n=== Filesystem-wide search for spreadsheets (bounded) ===")
exts = (".xlsx", ".xls", ".xlsm", ".csv", ".tsv", ".ods", ".parquet")
found = []
skip_dirs = {".cache", "__pycache__", "site-packages", "node_modules", "proc", "sys", "dist-packages", ".ipython", ".config"}
for r in ["/mnt", "/workspace", "/home", "/tmp", "/content", "/opt", "/srv", "/var", "/media", "/uploads", "/data"]:
    if not os.path.isdir(r):
        continue
    for dirpath, dirs, files in os.walk(r):
        dirs[:] = [d for d in dirs if d not in skip_dirs]
        for f in files:
            if f.lower().endswith(exts):
                found.append(os.path.join(dirpath, f))

if found:
    for f in found:
        try:
            print("  FOUND:", f, os.path.getsize(f), "B")
        except Exception as e:
            print("  FOUND:", f, f"(size err {e})")
else:
    print("  (no spreadsheet files found anywhere in the scanned roots)")
